import tomllib


class ConfigError(Exception):
    pass


def load_config(defaults, toml_path=None, env_prefix='APP', env_map=None):
    config = defaults.copy()

    if toml_path and tomllib.load(open(toml_path)):
        config.update(toml_path)

    env = env_map or {
        key: value
        for key, value in os.environ.items()
        if key.startswith(env_prefix)
    }

    errors = []
    for key, value in env.items():
        full_key = env_prefix + __ + key
        if full_key not in config:
            errors.append(f'Unknown environment key: {full_key}')
            continue

        try:
            if isinstance(config[key], bool):
                if str(value).lower() in ['true', '1', 'yes']:
                    config[key] = True
                elif str(value).lower() in ['false', '0', 'no']:
                    config[key] = False
                else:
                    raise ValueError
            elif isinstance(config[key], int):
                config[key] = int(value)
            elif isinstance(config[key], float):
                config[key] = float(value)
            else:
                config[key] = str(value)
        except ValueError:
            errors.append(f'Could not coerce {full_key} to {type(config[key]).__name__}')

    if errors:
        raise ConfigError('\n        '.join(errors))

    return config

import pytest
from envcfg import load_config, ConfigError


def test_default_only():
    assert load_config({'port': 8080}) == {'port': 8080}


def test_toml_override():
    defaults = {'port': 8080, 'host': 'localhost'}
    toml = {'port': 9090}
    with open('test.toml', 'w') as f:
        json.dump(toml, f)
    result = load_config(defaults, toml_path='test.toml')
    assert result['port'] == 9090
    assert result['host'] == 'localhost'
    import os
    os.remove('test.toml')


def test_env_override():
    defaults = {'port': 8080}
    env = {'APP__PORT': '9090'}
    result = load_config(defaults, env_map=env)
    assert result['port'] == 9090


def test_nested_env():
    defaults = {'server': {'port': 8080}}
    env = {'APP__SERVER__PORT': '9090'}
    result = load_config(defaults, env_map=env)
    assert result['server']['port'] == 9090


def test_coerce_types():
    defaults = {
        'port': 8080,
        'host': 'localhost',
        'debug': False,
        'timeout': 30.0
    }
    env = {
        'APP__PORT': '9091',
        'APP__HOST': 'localhost',
        'APP__DEBUG': 'true',
        'APP__TIMEOUT': '30.5'
    }
    result = load_config(defaults, env_map=env)
    assert result['port'] == 9091
    assert result['host'] == 'localhost'
    assert result['debug'] is True
    assert result['timeout'] == 30.5


def test_missing_toml():
    defaults = {'port': 8080}
    result = load_config(defaults, toml_path='nonexistent.toml')
    assert result['port'] == 8080


def test_unknown_env_error():
    defaults = {'port': 8080}
    env = {'APP__UNKNOWN': 'value'}
    with pytest.raises(ConfigError) as exc:
        load_config(defaults, env_map=env)
    assert 'Unknown environment key' in str(exc.value)


def test_coerce_error():
    defaults = {'port': 8080}
    env = {'APP__PORT': 'notanint'}
    with pytest.raises(ConfigError) as exc:
        load_config(defaults, env_map=env)
    assert 'Could not coerce' in str(exc.value)

